          anchor: "v1beta1-dynamographdeploymentrequestspec",
          kind: "type",
          description: "DynamoGraphDeploymentRequestSpec defines the desired state of a DynamoGraphDeploymentRequest.\nOnly the Model field is required; all other fields are optional and have sensible defaults.",
          underlyingType: "",
