          anchor: "v1beta1-kvtransferpolicy",
          kind: "type",
          description: "KvTransferPolicy configures topology-aware routing for KV-cache transfers\nbetween prefill and decode workers. This is a graph-wide concern placed\nunder `spec.experimental` while the API is incubating.",
          underlyingType: "",
          validation: "",
          appearsIn: [
            { name: "DynamoGraphDeploymentExperimentalSpec", anchor: "v1beta1-dynamographdeploymentexperimentalspec" },
          ],
          fields: [
            { name: "clusterTopologyName", type: "string", default: "", required: false, description: "clusterTopologyName references a Grove ClusterTopology CR. The operator<br />reads the CR's topology levels and projects them through Dynamo-owned pod<br />labels for worker topology metadata.", validation: "MinLength: 1 <br />Optional: \\{\\} <br />" },
            { name: "labelKey", type: "string", default: "", required: false, description: "labelKey is a Kubernetes node label key (e.g.<br />\"topology.kubernetes.io/zone\") whose value identifies the topology<br />domain for each worker. The operator copies the node label onto worker<br />pods so the runtime can publish it as worker metadata. The label<br />should correspond to the topology level named in `domain`.", validation: "MaxLength: 317 <br />MinLength: 1 <br />Pattern: `^(([a-z0-9]([-a-z0-9]\\{0,61\\}[a-z0-9])?)(\\.[a-z0-9]([-a-z0-9]\\{0,61\\}[a-z0-9])?)*/)?([A-Za-z0-9]([-A-Za-z0-9_.]\\{0,61\\}[A-Za-z0-9])?)$` <br />Optional: \\{\\} <br />" },
            { name: "domain", type: "[TopologyDomain](#v1beta1-topologydomain)", default: "", required: false, description: "domain is the logical name for the topology level to enforce<br />(e.g. \"zone\", \"rack\"). The router uses this to match workers that<br />share the same value for the label identified by `labelKey`.", validation: "Pattern: `^[a-z0-9]([a-z0-9-]*[a-z0-9])?$` <br />" },
            { name: "enforcement", type: "[KvTransferEnforcement](#v1beta1-kvtransferenforcement)", default: "required", required: false, description: "enforcement controls how the selected prefill worker's topology is<br />applied to decode routing. \"required\" only allows decode workers in the<br />same topology domain as the selected prefill worker. \"preferred\" keeps<br />all decode workers eligible, but biases selection toward workers in the<br />same topology domain. Defaults to \"required\".", validation: "Enum: [required preferred] <br />Optional: \\{\\} <br />" },
            { name: "preferredWeight", type: "float", default: "", required: false, description: "preferredWeight is required and used only when enforcement is<br />\"preferred\". Higher values create a stronger same-domain routing<br />preference, but do not guarantee same-domain selection. The value is not<br />a probability; worker selection still depends on load and other routing<br />inputs. A value of 0 disables the topology preference; 1 is the strongest<br />supported preference.", validation: "Maximum: 1 <br />Minimum: 0 <br />Optional: \\{\\} <br />" },
          ],
          enumValues: [
          ],
